"""Generates Rust sources from Linux rtw88 (GPL-2.0 OR BSD-3-Clause; used here under BSD-3-Clause):
register definitions (reg.h), the RTL8822B power sequences (rtw8822b.c) and PHY tables
(rtw8822b_table.c). Usage: python gen_rtw88.py <rtw88 dir> <out dir>"""
import re
import sys
from pathlib import Path

HEADER = """// Generated by crates/radio/tools/gen_rtw88.py from Linux rtw88 ({src}).
// Copyright(c) 2018-2019 Realtek Corporation. Used under the BSD-3-Clause license (see NOTICE.md).
// Do not edit.
"""


def c_expr_to_rust(expr, known):
    expr = expr.strip()
    expr = re.sub(r"\bBIT\((\d+)\)", r"(1u32 << \1)", expr)
    expr = re.sub(r"\bGENMASK\((\d+),\s*(\d+)\)", r"genmask(\1, \2)", expr)
    expr = re.sub(r"\b(0x[0-9A-Fa-f]+|\d+)[uUlL]+\b", r"\1", expr)
    expr = expr.replace("~", "!")
    for tok in re.findall(r"[A-Za-z_][A-Za-z0-9_]*", re.sub(r"\b0x[0-9A-Fa-f]+\b", "0", expr)):
        if tok in ("u32", "genmask"):
            continue
        if tok not in known:
            return None
    if re.search(r"[^\sA-Za-z0-9_()|&!<>+\-*x,]", expr):
        return None
    return expr


def gen_regs(srcs, out):
    text = "\n".join(s.read_text(encoding="utf-8") for s in srcs)
    text = re.sub(r"\\\n", " ", text)
    known, lines = set(), []
    for m in re.finditer(r"^#define\s+([A-Z][A-Z0-9_]*)\s+(.+?)\s*$", text, re.M):
        name, value = m.group(1), re.sub(r"/\*.*?\*/", "", m.group(2)).strip()
        if not value or name.startswith("__") or name in known:
            continue
        rust = c_expr_to_rust(value, known)
        if rust is None:
            continue
        known.add(name)
        lines.append(f"pub const {name}: u32 = {rust};")
    body = HEADER.format(src=", ".join(s.name for s in srcs)) + "#![allow(dead_code, unused_parens, clippy::all)]\n\n"
    body += "const fn genmask(h: u32, l: u32) -> u32 {\n    (u32::MAX >> (31 - h)) & !((1u32 << l) - 1)\n}\n\n"
    out.write_text(body + "\n".join(lines) + "\n", encoding="utf-8")
    return len(lines)


def gen_tables(src, out):
    text = src.read_text(encoding="utf-8")
    body = HEADER.format(src="rtw8822b_table.c") + "#![allow(clippy::all)]\n"
    counts = {}
    for name, rust in [("rtw8822b_mac", "MAC"), ("rtw8822b_agc", "AGC"), ("rtw8822b_bb", "BB"),
                       ("rtw8822b_rf_a", "RF_A"), ("rtw8822b_rf_b", "RF_B")]:
        m = re.search(r"static const u32 " + name + r"\[\] = \{(.*?)\};", text, re.S)
        vals = re.findall(r"0x[0-9A-Fa-f]+", m.group(1))
        counts[rust] = len(vals)
        rows = [", ".join(v.lower() for v in vals[i:i + 8]) for i in range(0, len(vals), 8)]
        body += f"\npub static {rust}: [u32; {len(vals)}] = [\n" + "".join(f"    {r},\n" for r in rows) + "];\n"
    out.write_text(body, encoding="utf-8")
    return counts


def gen_pwrseq(src, out):
    text = src.read_text(encoding="utf-8")
    consts = {"RTW_PWR_CUT_ALL_MSK": 0xFF, "RTW_PWR_INTF_SDIO_MSK": 1, "RTW_PWR_INTF_USB_MSK": 2,
              "RTW_PWR_INTF_PCI_MSK": 4, "RTW_PWR_INTF_ALL_MSK": 0xF, "RTW_PWR_ADDR_MAC": 0,
              "RTW_PWR_ADDR_USB": 1, "RTW_PWR_ADDR_PCIE": 2, "RTW_PWR_ADDR_SDIO": 3,
              "RTW_PWR_CMD_READ": 0, "RTW_PWR_CMD_WRITE": 1, "RTW_PWR_CMD_POLLING": 2,
              "RTW_PWR_CMD_DELAY": 3, "RTW_PWR_CMD_END": 4, "RTW_PWR_DELAY_US": 0, "RTW_PWR_DELAY_MS": 1}
    for i, c in enumerate("TABCDEFG"):
        consts[f"RTW_PWR_CUT_{c}_MSK" if c != "T" else "RTW_PWR_CUT_TEST_MSK"] = 1 << i

    def ev(e):
        e = re.sub(r"\bBIT\((\d+)\)", r"(1 << \1)", e.strip())
        for k, v in consts.items():
            e = re.sub(r"\b" + k + r"\b", str(v), e)
        return eval(e, {"__builtins__": {}})

    body = HEADER.format(src="rtw8822b.c") + "\nuse crate::chip::PwrCmd;\n"
    for name, rust in [("trans_carddis_to_cardemu_8822b", "CARDDIS_TO_CARDEMU"),
                       ("trans_cardemu_to_act_8822b", "CARDEMU_TO_ACT"),
                       ("trans_act_to_cardemu_8822b", "ACT_TO_CARDEMU"),
                       ("trans_cardemu_to_carddis_8822b", "CARDEMU_TO_CARDDIS")]:
        m = re.search(r"static const struct rtw_pwr_seq_cmd " + name + r"\[\] = \{(.*?)\n\};", text, re.S)
        cmds = []
        for entry in re.findall(r"\{([^{}]*)\}", m.group(1)):
            f = [ev(x) for x in entry.split(",")]
            offset, cut, intf, base, cmd, mask, value = f
            if cmd == 4:
                break
            if not intf & 2:  # USB only
                continue
            cmds.append(f"    PwrCmd {{ offset: 0x{offset:04x}, cut_mask: 0x{cut:02x}, base: {base}, cmd: {cmd}, mask: 0x{mask:02x}, value: 0x{value:02x} }},")
        body += f"\npub static {rust}: &[PwrCmd] = &[\n" + "\n".join(cmds) + "\n];\n"
    out.write_text(body, encoding="utf-8")


def main():
    src, out = Path(sys.argv[1]), Path(sys.argv[2])
    out.mkdir(parents=True, exist_ok=True)
    print("regs", gen_regs([src / "reg.h", src / "rtw8822b.h", src / "bf.h"], out / "regs.rs"))
    print("tables", gen_tables(src / "rtw8822b_table.c", out / "tables.rs"))
    gen_pwrseq(src / "rtw8822b.c", out / "pwrseq.rs")


if __name__ == "__main__":
    main()

